function QuizCard({ card, sessionId, display, lang }) {
  const labelId = useId()
  const questionId = useId()
  const ans = useCardAnswer(card, sessionId, lang)
  const sent = ans.answer && ans.answer.data
  const total = card.questions.length
  const [progress, setProgress] = useState(() => {
    const checkedNow = card.questions.map((_, i) => Boolean(sent || ans.draft?.checked?.[i]))
    // index === total is the result screen, reachable only once every question is checked.
    const wanted = sent ? total : Math.max(0, Math.min(total, ans.draft?.index ?? 0))
    return {
      index: wanted >= total && !checkedNow.every(Boolean) ? total - 1 : wanted,
      chosen: sent ? sent.answers.map(a => a.chosen) : card.questions.map((_, i) => ans.draft?.chosen?.[i] ?? null),
      checked: checkedNow
    }
  })
  const visible = sent ? { index: total, chosen: sent.answers.map(a => a.chosen), checked: card.questions.map(() => true) } : (ans.draft || progress)
  const { chosen, checked } = visible
  const index = Math.min(visible.index, checked.every(Boolean) ? total : total - 1)
  const inResult = index >= total
  const q = inResult ? null : card.questions[index]
  const headingRef = useRef(null)
  const previous = useRef(index)
  useEffect(() => {
    if (previous.current !== index) headingRef.current?.focus()
    previous.current = index
  }, [index])
  const update = change => {
    if (ans.locked) return
    const next = { ...visible, index, ...change }
    setProgress(next)
    ans.saveDraft(next)
  }
  const roving = useRovingFocus(q ? q.options.length : 1)
  const done = !inResult && checked[index]
  const allChecked = checked.every(Boolean)
  const isRight = i => chosen[i] === card.questions[i].answer
  const score = chosen.filter((v, i) => v === card.questions[i].answer).length
  const pick = option => {
    if (done || ans.locked || inResult) return
    update({ chosen: chosen.map((v, i) => i === index ? option : v) })
  }
  const check = () => { if (!inResult && chosen[index] !== null) update({ checked: checked.map((v, i) => i === index ? true : v) }) }
  const next = () => update({ index: index + 1 })
  const sendResult = () => { if (allChecked) ans.submit({ chosen }) }
  // The one thing Enter does right now.
  const primary = inResult ? sendResult : done ? next : check

  const onKeyDown = event => {
    if (ans.locked || event.defaultPrevented || event.ctrlKey || event.metaKey || event.altKey) return
    const tag = event.target && event.target.tagName
    if (tag === 'INPUT' || tag === 'TEXTAREA') return
    if (event.key === 'Enter') {
      event.preventDefault()
      primary()
    } else if (/^[1-9]$/.test(event.key) && q && !done && Number(event.key) <= q.options.length) {
      event.preventDefault()
      const i = Number(event.key) - 1
      pick(i)
      roving.refs.current[i] && roving.refs.current[i].focus()
    }
  }

  const bar = jsx('div', {
    className: 'huic-qsegs', role: 'progressbar', 'aria-label': card.title || t(lang, 'quizResult'),
    'aria-valuemin': 1, 'aria-valuemax': total, 'aria-valuenow': Math.min(index + 1, total),
    'aria-valuetext': inResult ? t(lang, 'quizResult') : t(lang, 'questionOf', { n: index + 1, total }),
    children: card.questions.map((_, i) => jsx('span', {
      className: cx('huic-qseg', checked[i] ? (isRight(i) ? 'huic-qseg-ok' : 'huic-qseg-bad') : null, i === index && 'huic-qseg-cur')
    }, i))
  })

  let body
  if (inResult) {
    body = [
      jsxs('div', {
        className: 'huic-score', role: 'status',
        children: [
          jsx('span', { className: 'huic-score-big', 'aria-hidden': true, children: `${score}/${total}` }),
          // The big number already says "1/2": the heading adds the word, screen readers get the sentence.
          jsxs('h4', { id: questionId, ref: headingRef, tabIndex: -1, className: 'huic-title', children: [
            jsx('span', { className: 'huic-sr', children: t(lang, 'score', { score, total }) }),
            jsx('span', { 'aria-hidden': true, children: t(lang, score === total ? 'quizAllRight' : 'quizScoreWord') })
          ] })
        ]
      }),
      jsx('ul', {
        className: 'huic-review',
        children: card.questions.map((item, i) => jsxs('li', {
          className: isRight(i) ? 'huic-review-ok' : 'huic-review-bad',
          children: [
            jsx('span', { className: 'huic-review-mark', 'aria-hidden': true, children: jsx(Icon, { name: isRight(i) ? 'check' : 'cross' }) }),
            jsxs('span', {
              className: 'huic-opt-text',
              children: [
                jsx('span', { className: 'huic-opt-label', children: item.question }),
                isRight(i) ? null : jsx('span', { className: 'huic-opt-desc', children: t(lang, 'correctAnswer', { x: item.options[item.answer] }) })
              ]
            })
          ]
        }, i))
      })
    ]
  } else {
    body = [
      jsx('h4', { id: questionId, ref: headingRef, tabIndex: -1, className: 'huic-title', children: q.question }),
      jsx('div', {
        role: 'radiogroup', 'aria-labelledby': questionId,
        className: done ? 'huic-quiz-done' : undefined,
        style: { display: 'flex', flexDirection: 'column', gap: 6 },
        children: q.options.map((option, i) => jsx(OptionTile, {
          option: { label: option }, index: i, num: i < 9 ? i + 1 : undefined,
          checked: chosen[index] === i, multiple: false,
          disabled: ans.locked, ariaDisabled: done,
          state: done ? (i === q.answer ? 'correct' : chosen[index] === i ? 'wrong' : undefined) : undefined,
          tabIndex: i === (chosen[index] ?? 0) ? 0 : -1,
          refCb: el => (roving.refs.current[i] = el),
          onKeyDown: roving.onKeyDown(i, pick), onToggle: () => pick(i)
        }, `${index}-${i}`))
      }),
      done ? jsxs('div', {
        role: 'status', className: cx('huic-callout', isRight(index) ? 'huic-callout-ok' : 'huic-callout-bad'),
        children: [
          jsxs('b', { children: [jsx(Icon, { name: isRight(index) ? 'check' : 'cross' }), t(lang, isRight(index) ? 'correct' : 'wrong')] }),
          q.explanation ? jsx('p', { children: q.explanation }) : null
        ]
      }) : null
    ]
  }

  const hintKey = inResult ? 'keySend' : done ? 'keyNext' : 'keyCheck'
  return jsx(Shell, {
    card, display, labelId, title: card.title,
    subtitle: inResult ? t(lang, 'quizResult') : t(lang, 'questionOf', { n: index + 1, total }),
    children: jsxs('div', {
      onKeyDown: ans.showActions ? onKeyDown : undefined,
      style: { display: 'flex', flexDirection: 'column', gap: 8 },
      children: [jsx('style', { children: KEYS_CSS + QUIZ_CSS }), bar, ...body]
    }),
    footer: ans.showActions ? jsx(Footer, {
      keys: t(lang, hintKey, { keys: keyRange(q ? q.options.length : 0) }),
      children: jsxs('span', { className: 'huic-foot-group', children: [
        index > 0 ? jsx(Btn, { onClick: () => update({ index: index - 1 }), children: t(lang, 'back') }) : null,
        inResult
          ? jsx(Btn, { variant: 'primary', disabled: !allChecked, onClick: sendResult, children: t(lang, 'sendScore') })
          : !done
            ? jsx(Btn, { variant: 'primary', disabled: chosen[index] === null, onClick: check, children: t(lang, 'check') })
            : jsx(Btn, { variant: 'primary', onClick: next, children: t(lang, index < total - 1 ? 'next' : 'seeResult') })
      ] })
    }) : null,
    after: ans.status
  })
}

// ── 80-renderer.js ──
// The tool media renderer: turns a hui_present tool result into a card.
// The result is untrusted (it may come from an older version or a hand-edited
// history), so it is validated again with the same schema; anything that does not
// pass falls back to the host's built-in attachment view, never a broken card.

const CARD_COMPONENTS = {}
const CARD_ID_RE = /^[a-z0-9][a-z0-9_-]{0,63}$/

function parseResult(result) {
  if (typeof result === 'string') {
    try {
      return JSON.parse(result)
    } catch {
      return null
    }
  }
  return result && typeof result === 'object' ? result : null
}

function sanitizeDisplay(display) {
  const out = { compact: false, accent: 'app', undo: 4 }
  if (display && typeof display === 'object') {
    if (display.compact === true) out.compact = true
    if (typeof display.accent === 'string' && ACCENT_VARS[display.accent]) out.accent = display.accent
    if ([0, 4, 8].includes(display.undo)) out.undo = display.undo
  }
  return out
}

// Read the current display settings from the backend once per profile/connection, when the first
// card of that scope is on screen (set by register(); a no-op without the backend route).
let loadDisplay = null
let displayRequested = null // the scope already asked
function requestDisplayOnce() {
  const scope = backendScope()
  if (displayRequested === scope || !loadDisplay) return
  displayRequested = scope
  loadDisplay()
}

function cardFromResult(result) {
  const parsed = parseResult(result)
  if (!parsed || !parsed.card || typeof parsed.card !== 'object' || Array.isArray(parsed.card)) return null
  const { cardId, ...rest } = parsed.card
  if (typeof cardId !== 'string' || !CARD_ID_RE.test(cardId)) return null
  const checked = validateCard(rest)
  if (!checked.card) return null
  const hasUndo = Boolean(parsed.display && [0, 4, 8].includes(parsed.display.undo))
  return { card: { cardId, ...checked.card }, display: sanitizeDisplay(parsed.display), hasUndo }
}

// Which mounted instance shows the card: a new one whenever the owner (source + profile) changes
// or the chat id changes other than by a confirmed runtime → stored move (confirmSessionMove), so
// nothing the user did in one chat or profile shows up in another. The confirmed move keeps the
// instance: what the user just picked in a new chat stays on screen.
function useCardIdentity(sessionId) {
  const owner = ownerScope()
  const seen = useRef(null)
  const prev = seen.current
  if (!prev) {
    seen.current = { owner, sessionId, generation: 0 }
  } else if (prev.owner !== owner || prev.sessionId !== sessionId) {
    const kept = prev.owner === owner && confirmSessionMove(prev.sessionId, sessionId)
    seen.current = { owner, sessionId, generation: kept ? prev.generation : prev.generation + 1 }
  }
  return seen.current.generation
}

function CardView({ result, sessionId, fallback }) {
  const parsed = useMemo(() => cardFromResult(result), [result])
  const chatId = typeof sessionId === 'string' && sessionId ? sessionId : null
  const generation = useCardIdentity(chatId)
  const display = useLiveDisplay(parsed ? parsed.display : null)
  const Component = parsed && CARD_COMPONENTS[parsed.card.type]
  useEffect(() => {
    if (Component && parsed.hasUndo) lastResultDisplay = { scope: backendScope(), display: parsed.display }
  }, [Component, parsed])
  useEffect(() => {
    if (Component) requestDisplayOnce() // every render: a profile switch reads that profile's values
  })
  if (!Component) return fallback ?? null
  const lang = cardLang(parsed.card)
  return jsx(
    Component,
    {
      card: parsed.card,
      display,
      sessionId: chatId,
      lang
    },
    // Not keyed by the chat id: a new chat's id changes from its runtime id to its stored id while
    // the card is on screen, and remounting then would drop what the user just did.
    `${parsed.card.cardId}\u0000${generation}`
  )
}

